define(['jquery', 'core/log', 'assignsubmission_cloudpoodll/cloudpoodllloader', "core/str", 'core/notification'], function ($, log, cloudpoodll, str, notification) {
    "use strict"; // jshint ;_;

    log.debug('submission helper: initialising');

    return {

        uploadstate: false,
        togglestate: 0,
        strings: {},


        init: function (opts) {
            this.component = opts['component'];
            this.safesave = opts['safesave'];
            this.recordertype = opts['recordertype'];

            this.register_controls();
            this.register_events();
            if (opts['localrecorder']) {
                this.setup_localrecorder();
            } else if (this.recordertype !== 'whiteboard') {
                this.setup_recorder();
            }
        },

        // The local recorder runs in the page and reports with a bubbling "localrecorder" event.
        setup_localrecorder: function () {
            var that = this;
            document.addEventListener('localrecorder', function (e) {
                var detail = e.detail || {};
                switch (detail.type) {
                    case 'recording':
                        if (that.safesave == 1) {
                            that.controls.formsubmitbutton.attr('disabled', 'disabled');
                        }
                        break;
                    case 'awaitingprocessing':
                        // Unlike the iframe recorders, a second recording replaces the first.
                        that.controls.updatecontrol.val(detail.mediaurl);
                        if (that.safesave == 1) {
                            that.controls.formsubmitbutton.removeAttr('disabled');
                        }
                        break;
                    case 'idle':
                        if (that.safesave == 1) {
                            that.controls.formsubmitbutton.removeAttr('disabled');
                        }
                        break;
                }
            });
        },

        setup_recorder: function () {
            var that = this;
            var recorder_callback = function (evt) {
                switch (evt.type) {
                    case 'recording':
                        if (evt.action === 'started') {
                            that.controls.updatecontrol.val();
                            //if opts safe save
                            if (that.safesave == 1) {
                                that.controls.formsubmitbutton.attr('disabled', 'disabled');
                            }
                        }
                        break;
                    case 'awaitingprocessing':
                        if (that.uploadstate != 'posted') {
                            that.controls.updatecontrol.val(evt.mediaurl);
                            //if opts safe save
                            if (that.safesave == 1) {
                                that.controls.formsubmitbutton.removeAttr('disabled', 'disabled');
                            }
                        }
                        that.uploadstate = 'posted';
                        break;
                    case 'error':
                        alert('PROBLEM:' + evt.message);
                        break;
                }
            };
            cloudpoodll.init(this.component + '_therecorder', recorder_callback);
        },


        register_controls: function () {
            var that = this;
            this.controls = {};
            this.controls.formsubmitbutton = $('#id_submitbutton');
            this.controls.deletebutton = $('.' + this.component + '_deletesubmissionbutton');
            this.controls.updatecontrol = $('#' + this.component + '_updatecontrol');
            this.controls.currentcontainer = $('.' + this.component + '_currentsubmission');
            this.controls.togglecontainer = $('.' + this.component + '_togglecontainer');
            this.controls.uploadfile = $('.' + this.component + '_uploadfile');
            this.controls.showrecorder = $('.' + this.component + '_showrecorder');
            this.controls.recordercontainer = $('#' + this.component + '_therecorder');
            this.original_data_type = this.controls.recordercontainer.attr('data-type');
            this.controls.togglebutton = $('.' + this.component + '_togglecontainer .togglebutton');
            this.controls.toggletext = $('.' + this.component + '_togglecontainer .toggletext');
            str.get_string('clicktohide', that.component).done(function (s) {
                that.strings['clicktohide'] = s;
            });
            str.get_string('clicktoshow', that.component).done(function (s) {
                that.strings['clicktoshow'] = s;
            });
            str.get_string('reallydeletesubmission', that.component).done(function (s) {
                that.strings['reallydeletesubmission'] = s;
            });
            str.get_string('confirm', that.component).done(function (s) {
                that.strings['confirm'] = s;
            });
            str.get_string('startagainupload', that.component).done(function (s) {
                that.strings['startagainupload'] = s;
            });
            str.get_string('startagainrecorder', that.component).done(function (s) {
                that.strings['startagainrecorder'] = s;
            });
            str.get_string('yes', that.component).done(function (s) {
                that.strings['yes'] = s;
            });
            str.get_string('no', that.component).done(function (s) {
                that.strings['no'] = s;
            });
        },

        register_events: function () {
            var that = this;
            this.controls.deletebutton.click(function () {
                if (that.controls.updatecontrol) {
                    if (confirm(M.util.get_string('reallydeletesubmission', that.component))) {
                        that.controls.updatecontrol.val(-1);
                        that.controls.currentcontainer.html('');
                    }
                }
            });
            this.controls.togglebutton.click(function () { that.toggle_currentsubmission(that); });
            this.controls.toggletext.click(function () { that.toggle_currentsubmission(that); });

            this.controls.uploadfile.click(function (e) {
                e.preventDefault();
                var btn = $(this);
                notification.confirm(
                    that.strings['confirm'],
                    that.strings['startagainupload'],
                    that.strings['yes'],
                    that.strings['no'],
                    function () {
                        btn.css('pointer-events', 'none');
                        setTimeout(function () {
                            btn.css('pointer-events', '');
                            btn.hide();
                            that.controls.showrecorder.show();
                            that.controls.recordercontainer.empty();
                            that.controls.recordercontainer.attr('data-type', 'upload').attr('data-alreadyparsed', 'false');
                            that.setup_recorder();
                        }, 100);
                    }
                );
            });

            this.controls.showrecorder.click(function (e) {
                e.preventDefault();
                var btn = $(this);
                notification.confirm(
                    that.strings['confirm'],
                    that.strings['startagainupload'],
                    that.strings['yes'],
                    that.strings['no'],
                    function () {
                        btn.hide();
                        that.controls.uploadfile.show();
                        that.controls.recordercontainer.empty();
                        that.controls.recordercontainer.attr('data-type', that.original_data_type).attr('data-alreadyparsed', 'false');
                        that.setup_recorder();
                    }
                );
            });
        },

        toggle_currentsubmission: function (that) {
            var doToggleState = function () {
                if (that.togglestate == 0) {
                    that.controls.togglebutton.removeClass('fa-toggle-off');
                    that.controls.togglebutton.addClass('fa-toggle-on');
                    that.controls.toggletext.text(that.strings['clicktohide']);
                    that.togglestate = 1;
                } else {
                    that.controls.togglebutton.removeClass('fa-toggle-on');
                    that.controls.togglebutton.addClass('fa-toggle-off');
                    that.controls.toggletext.text(that.strings['clicktoshow']);
                    that.togglestate = 0;
                }
            };
            that.controls.currentcontainer.toggle(
                { duration: 300, complete: doToggleState }
            );
            return false;
        }
    };//end of return object
});